    },
    {
      "compound": "Muscarine",
      "amount": "about 0.0002% of fresh weight (approximately 2 mg/kg fresh weight)",
      "effect": "A muscarinic acetylcholine receptor agonist that can cause sweating, salivation and bradycardia, but is present in trace amounts too low to explain fly agaric poisoning."
    },
    {
      "compound": "Stizolobic acid and stizolobinic acid",
      "amount": "unknown",
      "effect": "Pigment-related amino acid derivatives with no established psychoactive or toxic effect in humans at the amounts present."
    },
    {
      "compound": "Mannitol and trehalose",
      "amount": "several % of dry weight",
      "effect": "Fungal storage carbohydrates that are largely harmless, though large amounts may cause mild osmotic digestive upset."
    },
    {
      "compound": "Choline",
      "amount": "unknown",
      "effect": "A normal dietary nutrient and acetylcholine precursor with no toxic effect at these levels."
    },
    {
      "compound": "Vanadium (as accumulated metal, e.g. amavadine-type complexes)",
      "amount": "up to about 100-400 mg/kg dry weight",
      "effect": "Accumulated trace metal of uncertain human toxicity at dietary exposure levels from this mushroom."
    },
    {
      "compound": "Amatoxins and phallotoxins",
      "amount": "unknown",
      "effect": "Generally absent or only trace-level in this species, so the deadly hepatotoxic syndrome of Amanita phalloides is not typical of fly agaric."
    }
  ]
}

